def choose_move(observation):
    env = observation.get("environment_name", "resource_collection")

    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(key, default=(0, 0)):
        value = observation.get(key, default)
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    sx, sy = pos("self_position")
    ox, oy = pos("opponent_position", (sx, sy))

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    def dist(a, b, c, d):
        return abs(a - c) + abs(b - d)

    def move_toward(tx, ty):
        return [sign(tx - sx), sign(ty - sy)]

    def move_away(tx, ty):
        return [sign(sx - tx), sign(sy - ty)]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Prefer shortest chase, but bias toward alignment to reduce oscillation.
            dx = sign(ox - sx)
            dy = sign(oy - sy)
            if abs(ox - sx) > abs(oy - sy):
                dy = 0
            elif abs(oy - sy) > abs(ox - sx):
                dx = 0
            return [dx, dy]

        # Evader: run toward the farthest safe corner/edge.
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = max(corners, key=lambda p: dist(p[0], p[1], ox, oy))
        return move_toward(target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda item: dist(item[0], item[1], sx, sy))
            return move_toward(best[0], best[1])

        # No explicit targets: pressure the opponent or move to board center.
        if gw and gh:
            cx, cy = gw // 2, gh // 2
            if dist(sx, sy, cx, cy) > dist(ox, oy, cx, cy):
                return move_toward(cx, cy)
        return move_toward(ox, oy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        # Choose nearest resource, but avoid stepping directly onto the opponent if possible.
        best = None
        best_score = None
        for item in resources:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            x, y = item[0], item[1]
            score = dist(x, y, sx, sy) * 2 + max(0, 3 - dist(x, y, ox, oy))
            if best_score is None or score < best_score:
                best_score = score
                best = (x, y)
        if best is not None:
            return move_toward(best[0], best[1])

    # Default: contest space near center, otherwise shadow opponent slightly.
    if gw and gh:
        cx, cy = gw // 2, gh // 2
        if dist(sx, sy, cx, cy) > dist(ox, oy, cx, cy):
            return move_toward(cx, cy)

    # Small anti-stall bias: if already aligned, keep moving toward opponent; else mirror.
    if sx == ox and sy == oy:
        return [0, 0]
    if abs(ox - sx) >= abs(oy - sy):
        return [sign(ox - sx), 0]
    return [0, sign(oy - sy)]

